DROP TEMPORARY TABLE IF EXISTS dev_vault_items;
CREATE TEMPORARY TABLE dev_vault_items (wcid INT UNSIGNED PRIMARY KEY);
SELECT CASE
         WHEN it & 32769 THEN 901600
         WHEN it & 256 THEN 901601
         WHEN it & 14 THEN 901602
         WHEN it & 2048 AND (nm LIKE '%Portal%' OR nm LIKE '%Sending%') THEN 901603
         ELSE 901604 END, 4, wcid, -1, 0, 0, 0
FROM (SELECT d.wcid, COALESCE((SELECT value FROM weenie_properties_int p WHERE p.object_Id = d.wcid AND p.type = 1), 0) it, COALESCE((SELECT value FROM weenie_properties_string s WHERE s.object_Id = d.wcid AND s.type = 1), '') nm
      FROM dev_vault_items d JOIN weenie w ON w.class_Id = d.wcid) x
WHERE (it & 1048576) = 0 AND nm <> ''
ORDER BY 1, nm, wcid;
